q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(71, 'a-room-not-yet-lived-in', 'A room not yet lived in', 'The new room offers possibility but cannot quiet the speaker’s unsettled inner life. A low view of preparation materials keeps that provisional feeling without inventing the person or making construction mess picturesque.', 'Horizontal 3:2 graphite and muted blue-grey gouache. Low oblique close view of a freshly plastered plain room corner, smooth grey wall meeting a pale marbled floor. At left edge a cropped ordinary metal paint bucket with a little dried pale blue paint on its rim; lid rests flat nearby. One slack red insulated cord and one blue insulated cord lie loosely along the base of the wall and cross once naturally, disconnected ends out of frame, no sparks or exposed copper. Broad empty clean floor across right half, ordinary soft daylight. Minimal small dust near unfinished skirting only, no rubble, peeling walls, ornate furniture, human, portrait, writing, labels or theatrical shadows. Coherent contact and corner perspective, selective graphite marks rather than equal detail everywhere.'), (77, 'the-household-commentator', 'The household commentator', 'The playful poem describes a talkative pet bird with strong preferences and a place in family life. A small green parakeet is an illustrative interpretation, not a claim about the poet’s actual pet or its species; attention and posture carry the humour without human costume.', 'Horizontal 3:2 loose transparent watercolor and fine pencil. One small green parakeet on a simple natural wood perch near a plain domestic window, placed slightly left of centre in three-quarter side view. Its head is tilted slightly as if listening to someone outside frame, beak closed, lively but ordinary dark eye, folded wings, long tail below perch. Two feet grip the branch plausibly, far foot partly hidden; avoid extra toes. A small plain dish holding a few sunflower seeds is partly cropped at the bottom left. Quiet pale wall and diffuse window light across right half. No cage bars, human, hat, spectacles, printed book, speech bubble, music notes, other birds or text. Keep plumage softly simplified and varied, no jeweled feather detail or cartoon expression.'), (83, 'red-cloth-in-the-late-light', 'Red cloth in the late light', 'The opening folds peace into a red sari before moving through memory and mortality. One loosely folded red cotton sari can hold embodied memory without inventing a dying woman, family photographs or religious montage.', 'Horizontal 3:2 dry pastel and restrained gouache material study. A plain deep alizarin-red cotton sari lies loosely folded over one end of a low simple wooden bed, the fold falling naturally over the edge into a short hanging drape at lower right. No ornate gold border, embroidery or invented regional textile pattern. Soft late-afternoon light touches just a few raised folds; deep red recesses remain unresolved. Most upper and left frame quiet pale wall and a small plain portion of bed surface. Cloth weight, compression and overlapping folds physically believable, no gravity-defying waves. No person, face, body shape under fabric, jewellery, diary, photographs, musical instruments, ceremonial objects, text or watermark. Dignified warmth and stillness without theatrical death cues.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-03/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
